export const COMPONENT = 'mootimetertool_wordcloud';

export type Answer = {
    id: number;
    text: string;
    fullName: string;
    createdAt: string;
};

export type WordcloudData = {
    pageId: number;
    ownAnswers: Answer[];
    maxAnswers: number;
    allowDuplicateAnswers: boolean;
};

export type Word = {
    text: string;
    count: number;
};

export type WordcloudResults = {
    available: boolean;
    words: Word[];
};
